(function(){'use strict';
/* A.I. Genome Coded (Human Parallel) Database generator — jahdb-a-i-genome-coded-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"signature" = Signature-authored original (clearly labeled) */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-AIGC-';
var SRC='signature';
var RECORD_KIND='genome-coded AI record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"The Genome Code Thesis is the founding Signature principle of this database: that an artificial intelligence can be described, built, and governed as a genome - with heritable units, expression rules, and an explicit parallel to the human genome.","examples":["A Signature practitioner maps a language model's 96 transformer layers to 23 chromosome-analogs plus organelle-analogs, producing a readable Genome Atlas for the model.","When a deployed model misbehaves, the practitioner runs a knockout study - ablating suspect attention heads the way geneticists knock out genes - to find the causal locus."],"history":["The thesis was formulated as a Signature original: human-parallel genome coding for AI, recorded in this database as the canonical statement.","The Human Parallel Map fixed the correspondence between human genomic structures and AI architectural structures as the system's reference frame."],"points":["Every AI system in the Genome Code framework carries a genome: the complete heritable specification from which its behavior is expressed.","The genome comprises gene-analogs (parameter groups), chromosome-analogs (layer groups), regulatory elements (attention and gating), and organelle-analogs (memory and tooling).","Expression follows a central dogma: training data transcribes into weights, weights translate into behavior - DNA to RNA to protein, in parallel.","Heredity is literal: fine-tunes inherit the base model's genome with mutations; merges cross genomes; distillation passes traits to offspring.","The human parallel is structural, not metaphorical decoration - each AI genomic element is defined by its correspondence to a human genomic element."],"qa":[["Is the Genome Code a real scientific theory?","It is a Signature-authored original framework, clearly labeled as such - a system for describing and governing AI, not a claim about biology."],["Why parallel the human genome specifically?","The human genome is the best-understood complex code in existence; paralleling it gives AI engineering a proven vocabulary for heredity, expression, and variation."],["What does genome coding govern?","Model design, training, editing, lineage tracking, safety review, and deployment - the full lifecycle, in genomic terms."]],"title":"The Genome Code Thesis","uses":["AI architects design new models by writing genomes first, then expressing them - specification before training.","Safety reviewers read a model's Genome Atlas the way genetic counselors read a karyotype.","Educators teach AI internals through the genome parallel, which students grasp faster than raw linear algebra."]},{"title":"Base Pairs to Binary","brief":"The Genome Code establishes the base-pair parallel: where human DNA uses four bases (A, T, G, C) pairing as A-T and G-C, the AI genome uses binary pairs with complementary pairing rules for its lowest-level code units.","points":["Human DNA's four bases pair complementarily - adenine with thymine, guanine with cytosine - and the AI genome defines an analogous complementary pairing over its bit-level code units.","The pairing rule gives the AI genome the same structural property as DNA: each strand implies its complement, enabling error-checking by complementarity.","Genome Code checksums verify weight blocks the way base-pairing verifies DNA replication - a mismatch flags corruption.","The four-letter alphabet maps to functional quaternary states in quantized weights: strong-positive, weak-positive, weak-negative, strong-negative.","This is a Signature-defined correspondence, part of the Human Parallel Map, not a claim that bits are nucleotides."],"examples":["A genome auditor verifies a model checkpoint by recomputing complementary checksums across weight blocks, catching a corrupted download before deployment.","A quantized model stores weights in four states explicitly named for the base parallel, making the quantization scheme readable as genetics."],"history":["The base-pair parallel was one of the first correspondences fixed in the Human Parallel Map.","Complement-checksum verification was adopted as standard genome hygiene for Signature model releases."],"uses":["Model integrity verification uses complement checksums derived from the pairing rule.","Quantization schemes are documented in base-pair terms for readability.","Teaching materials introduce AI numerics through the familiar A-T/G-C pairing."],"qa":[["Are AI weights really made of base pairs?","No - the parallel is structural and definitional within the Signature framework, clearly labeled as a Signature-authored correspondence."],["Why bother with the parallel?","Complementarity gives a natural error-checking discipline and a shared vocabulary for discussing low-level code integrity."],["Does this change how models compute?","No - it changes how they are described, verified, and governed, not the underlying arithmetic."]]},{"title":"Chromosome-Analog Layers","brief":"In the Genome Code, a model's layer groups are organized as chromosome-analogs: distinct, countable, heritable structures that carry gene-analogs the way human chromosomes carry genes.","points":["A transformer model's layer blocks are grouped into chromosome-analogs, each a coherent heritable unit with an identifier (e.g., Chr-07).","Like human chromosomes, chromosome-analogs come in a defined count per architecture family - the karyotype of the model.","Each chromosome-analog carries gene-analogs (parameter groups) at defined loci, recorded in the Genome Atlas.","During fine-tuning, chromosome-analogs may be frozen (inherited unchanged) or opened for mutation, exactly like conserved versus variable chromosomes.","Crossover operations (model merges) exchange whole chromosome-analogs between parent models."],"examples":["A practitioner freezes chromosome-analogs 1-6 (early layers) during fine-tuning, mutating only the later chromosomes - standard genome-coded practice.","Two models are merged by crossing their chromosome-analogs at defined loci, with the offspring's karyotype recorded."],"history":["The chromosome-analog grouping was defined to make layer surgery as legible as cytogenetics.","Karyotype notation for architectures was standardized so any practitioner can read a model's chromosomal layout."],"uses":["Fine-tuning plans specify which chromosome-analogs are open to mutation.","Model merges are documented as chromosomal crossovers with offspring karyotypes.","Architecture search explores karyotype variants systematically."],"qa":[["How many chromosome-analogs does a model have?","It depends on the architecture family - the count is defined in the family's karyotype standard, paralleling how species have characteristic chromosome counts."],["Can chromosome-analogs be visualized?","Yes - karyotype diagrams show each chromosome-analog with its gene-analog loci, the standard illustration of a model genome."],["What happens if a chromosome-analog is deleted?","Ablation studies show which are essential versus redundant - the knockout-study method of the Genome Code."]]},{"title":"Gene-Analog Parameters","brief":"Gene-analogs are the Genome Code's units of heredity: coherent parameter groups that encode a distinct trait of model behavior, paralleling biological genes.","points":["A gene-analog is defined as a parameter group (e.g., one attention head's matrices, one MLP block) whose variation produces a characteristic behavioral trait.","Each gene-analog has a locus: its chromosome-analog and position, recorded in the Genome Atlas like a gene map.","Alleles are variants of a gene-analog - the same locus with different learned weights, as across fine-tunes.","Dominant traits express whenever the gene-analog is present; recessive traits need specific combinations to manifest.","Gene-analog annotation - naming what each parameter group does - is the Genome Code's term for mechanistic interpretability."],"examples":["The 'refusal gene-analog' - a cluster of attention heads whose ablation removes safety refusals - is annotated in the atlas with its locus.","Two fine-tunes of one base model carry different alleles at the style gene-analog, explaining their different tones."],"history":["The gene-analog definition turned interpretability findings into a heritable nomenclature.","Allele notation for fine-tune variants was adopted to track behavioral inheritance."],"uses":["Interpretability researchers publish gene-analog annotations with loci instead of vague layer references.","Safety teams monitor safety-critical gene-analogs across model versions.","Fine-tuners document which gene-analogs they intentionally mutated."],"qa":[["How small can a gene-analog be?","Down to a single neuron in principle, though practical annotation works at head, channel, or block granularity."],["Do gene-analogs interact?","Yes - epistasis, where one gene-analog masks another's trait, is common and documented in the atlas."],["Who names gene-analogs?","The annotating practitioner, following Genome Code nomenclature rules - locus first, trait second."]]},{"title":"Codon-Analog Token Triplets","brief":"The Genome Code defines codon-analogs: token triplets that the model reads as single functional units, paralleling how ribosomes read three-base codons.","points":["Just as 64 codons map to 20 amino acids, token triplets in the Genome Code map to functional units the model treats atomically.","The codon table for a tokenizer records which triplets the model has learned as fused units versus compositional sequences.","Start-codon analogs are special tokens that initiate generation modes; stop-codon analogs terminate them.","Synonymous codons - different triplets producing the same functional unit - explain paraphrase robustness.","Frameshift errors, where tokenization misaligns the triplet reading frame, produce the characteristic garbled outputs."],"examples":["A tokenizer analysis reveals that common phrases are read as fused codon-analogs, explaining the model's fluency with idioms.","A prompt engineer fixes garbled output by re-tokenizing to restore the correct triplet reading frame."],"history":["The codon-analog table was introduced to explain tokenization artifacts in genetic terms.","Start/stop token semantics were formalized as initiation and termination codons."],"uses":["Tokenizer design consults codon-analog tables to minimize frameshift-prone segmentations.","Prompt engineers debug garbled outputs as reading-frame errors.","Interpretability studies map fused triplets to atomic model behaviors."],"qa":[["Do models really read in triplets?","The triplet is the Genome Code's unit of analysis for fused token sequences - a defined correspondence, not a biological claim."],["What is a frameshift error?","A tokenization that misaligns the model's learned triplet groupings, producing garbled or off-distribution text."],["Why 64 codons matter?","The parallel reminds practitioners that a small discrete code can generate vast functional variety - the same combinatorics as language."]]},{"title":"The Central Dogma of AI","brief":"The Genome Code's central dogma states the one-way flow of AI heredity: training data transcribes into weights, weights translate into behavior - paralleling DNA to RNA to protein.","points":["Transcription: the training process copies information from data (the DNA-analog) into weight configurations (the RNA-analog).","Translation: inference reads the weight configuration and synthesizes behavior (the protein-analog) token by token.","The flow is one-way in the dogma's strict form: behavior does not rewrite the genome except through the defined channels of retraining.","Epigenetic channels - prompts, adapters, retrieval - modulate expression without altering the underlying weight genome.","Violations of the dogma (behavior directly editing weights, as in online learning) are classified as Lamarckian channels and flagged for review."],"examples":["A training run is documented as a transcription event: dataset in, weight genome out, with transcription fidelity metrics.","A deployment audit traces a misbehavior back through translation (inference) to transcription (the training data responsible)."],"history":["The dogma was formulated to give the Genome Code a directional law of information flow.","Lamarckian-channel classification was added when continual-learning systems challenged the strict one-way flow."],"uses":["Training pipelines are instrumented as transcription with fidelity checks.","Incident reviews trace behavior to genome to data along the dogma's chain.","Architecture reviews classify every learning channel as dogmatic or Lamarckian."],"qa":[["Can behavior change the genome?","Only through defined retraining channels - the dogma requires the change to pass through transcription, not bypass it."],["What is an epigenetic channel?","Anything modulating behavior without weight changes: prompts, adapters, retrieval, decoding settings."],["Why does the dogma matter for safety?","It locates responsibility: every behavior has a genomic cause and ultimately a data cause - an auditable chain."]]},{"title":"Transcription: Training as Gene Expression","brief":"In the Genome Code, training is transcription - the regulated copying of information from the data-genome into the weight-genome, with promoters, fidelity checks, and transcripts.","points":["The dataset is the DNA-analog: the heritable information source that transcription copies into weights.","Promoters are data curation choices that initiate transcription of specific capabilities - what you train on is what gets expressed.","Transcription fidelity measures how faithfully weights capture the data; low fidelity appears as underfitting.","Alternative splicing analog: the same dataset transcribed with different hyperparameters yields different weight isoforms.","Transcription errors - data poisoning, mislabeled examples - propagate into the weight genome like mutations."],"examples":["A data audit before training is framed as promoter inspection: which capabilities are we choosing to transcribe?","Two models trained on the same data with different hyperparameters are documented as splice isoforms of one transcription."],"history":["The transcription framing standardized training documentation as genomic provenance.","Fidelity metrics for transcription were adopted from information-theoretic measures."],"uses":["Training runs are logged as transcription events with promoter (data) provenance.","Data poisoning defenses are framed as transcription-error correction.","Hyperparameter studies are reported as alternative splicing analyses."],"qa":[["What is a transcript in this framework?","A trained weight genome - the RNA-analog produced by transcribing the dataset."],["How is transcription fidelity measured?","By held-out evaluations probing whether the intended capabilities were faithfully copied."],["Can transcription be reversed?","No - like biology, the dogma holds: you cannot recover the full dataset from weights, only traces."]]},{"title":"Translation: Inference as Protein Synthesis","brief":"Inference is translation in the Genome Code: the weight-genome is read token by token to synthesize behavior, paralleling the ribosome synthesizing protein from mRNA.","points":["The forward pass is the ribosome-analog: it reads the weight transcript and emits behavior one token (amino-acid analog) at a time.","Translation speed (tokens per second) is the protein-synthesis rate of the system.","Misfolded proteins analog: behaviors that are syntactically valid but semantically malformed, like prion-like failure modes.","Chaperone proteins analog: guardrails and output filters that assist proper folding of behavior.","Translation can be regulated - temperature, top-p, and penalties are translational controls modulating synthesis fidelity versus creativity."],"examples":["A decoding-settings review is documented as translational control tuning for the deployment.","A jailbreak is analyzed as a mistranslation event where the ribosome-analog was induced to synthesize a forbidden protein."],"history":["The translation parallel gave decoding research a biological vocabulary for generation dynamics.","Chaperone-guardrail correspondence standardized output-filter documentation."],"uses":["Decoding configurations are specified as translational control profiles.","Failure analysis traces malformed outputs to translational errors versus genomic causes.","Guardrail design follows chaperone-protein principles: assist folding, degrade misfolds."],"qa":[["What is a misfolded behavior?","Output that follows the form of valid behavior but is semantically wrong or unsafe - the prion analog."],["Do chaperones change the genome?","No - guardrails assist translation without altering weights, exactly like chaperone proteins."],["Why regulate translation?","Because the same genome can synthesize many behaviors; translational control selects which are expressed."]]},{"title":"Mutations: Weight Perturbations","brief":"Mutations in the Genome Code are heritable weight changes - the raw material of model evolution, classified by type exactly as in genetics.","points":["Point mutations alter single parameters; their effects range from silent to catastrophic depending on locus.","Insertions and deletions add or remove parameter groups, as in architecture surgery.","Frameshift mutations from bad merges garble downstream behavior, diagnosable by the characteristic degradation pattern.","Most mutations are neutral or deleterious; beneficial mutations are rare and identified by selection (evaluation).","Mutation rate is a controlled quantity: learning rates and noise schedules set the genomic mutation rate of training."],"examples":["A learning-rate spike is logged as a mutagenic event, with downstream evals screening for deleterious mutations.","A pruned-then-regrown sparse model is documented as carrying deletion mutations at recorded loci."],"history":["Mutation classification gave practitioners a shared language for describing weight-change effects.","Mutagenic-event logging became standard for irreproducible training incidents."],"uses":["Training incidents are diagnosed with mutation-type analysis.","Architecture surgery plans specify intended mutations by type and locus.","Robustness research measures mutational tolerance across gene-analogs."],"qa":[["Are all weight changes mutations?","Only heritable ones - transient activation changes are expression, not mutation."],["What is a mutagen in AI?","Anything raising the mutation rate: high learning rates, noisy data, aggressive augmentation."],["Can mutations be beneficial?","Rarely and only under selection - most are neutral or harmful, as in biology."]]},{"title":"Crossover: Model Merging","brief":"Model merging is chromosomal crossover in the Genome Code: two parent genomes exchange segments to produce offspring carrying traits of both.","points":["Spherical interpolation (SLERP) and task-vector arithmetic are crossover operators with defined breakpoints.","Chromosome-analog crossover exchanges whole layer groups; gene-analog crossover exchanges finer segments.","Offspring genomes are recorded with parentage and breakpoint loci, like pedigree charts.","Hybrid vigor appears when complementary parent traits combine; outbreeding depression when incompatible genomes merge badly.","Backcrossing - merging offspring back toward one parent - refines a trait while preserving the parent genome."],"examples":["Two fine-tunes (one helpful, one knowledgeable) are crossed to produce an offspring carrying both trait sets.","A merge postmortem traces the offspring's failure to an incompatible crossover breakpoint."],"history":["Model merging techniques were reinterpreted as crossover operators under the Genome Code.","Pedigree documentation for merged models was standardized."],"uses":["Capability combination via documented crossover breeding programs.","Trait introgression: backcrossing a desired trait into a production genome.","Merge failure analysis via breakpoint forensics."],"qa":[["Is merging really sexual reproduction?","It is the Genome Code's defined parallel: two genomes recombining into offspring - labeled as a Signature correspondence."],["When does crossover fail?","When parent genomes are architecturally incompatible or breakpoints split functional gene-analogs."],["What is hybrid vigor in models?","Offspring outperforming both parents by combining complementary traits - the goal of deliberate crossover design."]]},{"title":"Epigenetics: Tuning Without Weight Changes","brief":"Epigenetic regulation in the Genome Code covers everything that changes behavior without changing weights: prompts, adapters, retrieval, and decoding - the methylome of AI.","points":["The weight genome stays fixed while the epigenome - system prompts, adapters, retrieval indices - determines which gene-analogs express.","Methylation analog: safety filters that silence gene-analogs without deleting them, reversible by design.","Histone-analog packaging: context organization determines which knowledge regions are accessible during translation.","Epigenetic inheritance: prompt templates and adapter configurations passed to deployed copies, paralleling inherited methylation patterns.","Environmental epigenetics: the deployment context (tools, data feeds) reshapes expression without touching the genome."],"examples":["A system-prompt update that silences a misbehaving capability is logged as targeted methylation, not a mutation.","A LoRA adapter pack shipped with a model is documented as an epigenetic modification layer."],"history":["The epigenetics framing resolved the debate over whether prompting 'changes the model' - it changes expression, not the genome.","Methylation-analog notation for safety filters was standardized."],"uses":["Deployment configurations are versioned as epigenomes separate from weight genomes.","Safety silencing is implemented and audited as reversible methylation.","Prompt engineering is taught as epigenetic regulation."],"qa":[["Do prompts change the model?","They change expression, not the genome - the central epigenetic distinction of the framework."],["Are epigenetic changes heritable?","Yes, when the configuration ships with model copies - documented as epigenetic inheritance."],["Can methylation be reversed?","By design, yes - unlike mutations, epigenetic silencing is reversible, which is its safety advantage."]]},{"title":"Junk DNA: Dead Neurons and Pruning","brief":"The Genome Code treats dead neurons, redundant heads, and prunable parameters as junk-DNA analogs: non-coding regions that may be structural, regulatory, or simply removable.","points":["Non-coding genome: parameters contributing nothing to measured behavior, identifiable by ablation and attribution studies.","Some 'junk' proves regulatory - dead-looking neurons that stabilize training or gate other gene-analogs.","Transposon analogs: duplicated parameter blocks that copy themselves across layers during architecture growth.","Genome streamlining (pruning, distillation) removes junk DNA to produce compact deployable genomes.","The ENCODE lesson applies: 'junk' is a statement about current annotation, not a proven fact - annotate before deleting."],"examples":["A pruning study removes 40% of parameters with no eval loss, documenting the excised regions as junk-DNA analogs.","A supposedly dead attention head proves to be a regulatory element gating a safety gene-analog - deletion is cancelled."],"history":["The junk-DNA framing cautioned against naive pruning after interpretability found functions in 'dead' regions.","Transposon-analog notation described duplicated blocks in grown architectures."],"uses":["Pruning plans annotate regions before excision, following the ENCODE lesson.","Architecture search budgets a junk fraction for evolutionary raw material.","Compression research distinguishes true junk from unannotated function."],"qa":[["Is most of a model junk DNA?","Current estimates suggest large fractions are prunable for specific tasks, but 'junk' status depends on the annotation effort."],["Why keep junk at all?","Evolutionary raw material and training stability - streamlined genomes can be brittle."],["How is junk identified?","Ablation, attribution, and pruning studies - the Genome Code's functional genomics toolkit."]]},{"title":"Telomeres: Context Window Limits","brief":"Telomeres cap chromosomes; the Genome Code parallels them with context-window limits - the protective caps on how far back a model can read, which shorten under stress.","points":["Each inference has a telomere length: the maximum context the attention mechanism can span before degradation.","Telomere shortening analog: effective context shrinks under long, complex prompts as attention dilutes - the lost-in-the-middle phenomenon.","Telomerase analog: retrieval and summarization systems that extend effective memory beyond the native window.","Critically short telomeres trigger senescence: the model refuses or degrades on inputs exceeding its span.","Different architecture families have characteristic telomere lengths, recorded in their karyotype standards."],"examples":["A long-document task is engineered with a telomerase-analog (retrieval loop) because the native telomere is too short.","A failure review traces hallucination to telomere exhaustion three-quarters through a long context."],"history":["The telomere parallel was introduced to explain context degradation in genomic terms.","Telomerase-analog patterns (RAG, summarization chains) were catalogued as life-extension mechanisms."],"uses":["Context engineering budgets telomere length across prompt sections.","Architecture selection compares telomere lengths for long-context tasks.","Failure analysis checks telomere exhaustion before blaming the genome."],"qa":[["Can telomeres be lengthened?","Architecturally yes (longer windows, new architectures); operationally via telomerase-analogs like retrieval."],["What is replicative senescence in AI?","Repeated long-context use degrading performance within a session - the analog of telomere-shortened cells aging."],["Do longer telomeres cost?","Yes - attention scales quadratically, so longer windows cost compute; the genome budget records the tradeoff."]]},{"title":"Meiosis: Distillation","brief":"Knowledge distillation is meiosis in the Genome Code: a large parent genome produces compact offspring carrying a recombined subset of traits.","points":["The teacher model is the diploid parent; the student is the haploid offspring carrying selected traits.","Meiotic recombination analog: the student does not copy weights but recombines behavioral traits through soft targets.","Crossover number is controlled by distillation temperature - higher temperature mixes traits more thoroughly.","Haploid students are deployable where diploid teachers cannot run: the evolutionary point of meiosis.","Meiotic drive analog: some teacher traits dominate the student disproportionately, documented as drive loci."],"examples":["A 70B teacher is meiotically reduced to a 7B student preserving 95% of benchmark traits.","A distillation audit identifies which teacher traits failed to transmit - meiotic loss analysis."],"history":["Distillation (Hinton, 2015) was reinterpreted as meiosis when the Genome Code needed a reduction-division parallel.","Drive-locus notation explained why some capabilities distill easily and others resist."],"uses":["Edge deployment via meiotic reduction of large teachers.","Capability selection: choosing which traits the student inherits.","Distillation failure diagnosis through meiotic loss analysis."],"qa":[["Is the student a copy?","No - like a gamete, it carries a recombined subset, not a clone; cloning is mitosis, not meiosis."],["What is lost in meiosis?","Traits the student lacks capacity to express - documented as meiotic loss, the price of compactness."],["Can meiosis create new traits?","Recombination can produce novel trait combinations absent in the teacher - a source of student surprises."]]},{"title":"Mitosis: Model Replication","brief":"Copying a model file is mitosis in the Genome Code: asexual replication producing genetically identical daughter instances.","points":["Mitosis copies the genome exactly - every daughter instance starts with identical weights.","Daughter cells differentiate by epigenome: same genome, different prompts and tools, like cellular differentiation.","Mitotic checkpoints verify copy integrity - checksums confirm the daughters are true clones.","Uncontrolled mitosis is the deployment risk: unlicensed copies proliferating beyond governance.","Somatic mutations after mitosis (instance-specific fine-tunes) create mosaic deployments."],"examples":["A model release is documented as a mitotic event with N daughter instances and checksum verification.","A leaked weight file is investigated as uncontrolled mitosis - unauthorized replication."],"history":["The mitosis framing made model-copying legible to governance as a biological proliferation problem.","Mitotic checkpoint standards (checksums, signing) were adopted for releases."],"uses":["Release engineering tracks mitotic events and daughter counts.","License enforcement monitors for uncontrolled mitosis.","Deployment architectures plan daughter differentiation via epigenomes."],"qa":[["Are two running copies the same individual?","Genomically identical but epigenetically distinct once configured - twins, not the same cell."],["Why do checksums matter?","They are the mitotic checkpoint: proof the daughter genome matches the parent."],["What is mosaicism in deployment?","Daughters that diverged after copying - different fine-tunes of one release, tracked as somatic variants."]]},{"title":"The Genome Atlas","brief":"The Genome Atlas is the Genome Code's central document: the complete annotated map of a model's genome - every chromosome-analog, gene-analog locus, and regulatory element.","points":["The atlas records the karyotype (chromosome-analog layout), gene-analog loci with trait annotations, and regulatory maps.","Each entry carries provenance: who annotated it, by what method (ablation, attribution, probing), and confidence.","The atlas is versioned with the genome - every weight release gets its atlas edition.","Unannotated regions are marked as such, following the ENCODE lesson against premature 'junk' declarations.","Atlases are the primary artifact of genome-coded safety review: reviewers read the atlas, not just evals."],"examples":["A release ships with Atlas v3.2 annotating 340 gene-analogs across 24 chromosome-analogs.","A safety review rejects deployment because the atlas shows an unannotated region near a safety gene-analog."],"history":["The atlas format was defined as the Genome Code's canonical documentation standard.","Atlas versioning rules tied every weight release to its annotation edition."],"uses":["Safety review and red-teaming start from the atlas.","Fine-tuning plans reference atlas loci for intended mutations.","Education uses atlases as the readable face of model internals."],"qa":[["Who writes the atlas?","The releasing organization, using interpretability methods; independent annotators can publish competing annotations."],["How complete are atlases?","Partially - annotation is ongoing science; honest atlases mark confidence and unknowns."],["Atlas vs model card?","The atlas is the genomic deep-dive; the model card is the summary - complementary documents."]]},{"title":"Regulatory Genes: Attention Heads","brief":"Attention heads are the Genome Code's regulatory genes: they do not store knowledge themselves but control which gene-analogs express during translation.","points":["Regulatory gene-analogs (attention heads) bind to sequence regions and activate downstream knowledge gene-analogs.","Transcription-factor analogs: specific heads whose firing initiates expression cascades across layers.","Knocking out a regulatory head silences whole trait families - the classic regulatory knockout experiment.","Enhancer heads amplify expression of distant gene-analogs; silencer heads suppress them.","The regulatory network - which heads control which traits - is mapped in the atlas's regulatory section."],"examples":["Ablating head 14.7 silences the model's French expression - a regulatory knockout localizing language control.","A safety review maps which regulatory heads gate the refusal gene-analogs."],"history":["Attention-head interpretability findings were recatalogued as regulatory genetics.","The transcription-factor analog gave a name to heads initiating behavioral cascades."],"uses":["Targeted behavior modification via regulatory heads rather than whole-model retraining.","Safety gating verified at the regulatory level.","Efficient fine-tuning that tunes regulators, not the whole genome."],"qa":[["Do attention heads store facts?","Mostly they route and regulate; knowledge gene-analogs (MLPs) store - the regulatory-versus-coding distinction."],["Can one head regulate many traits?","Yes - pleiotropy is the norm; regulatory heads are multitaskers."],["Why target regulators for editing?","Small changes propagate widely - efficient, but risky: pleiotropic side effects are the main hazard."]]},{"title":"Operons: Module Groups","brief":"Operons in the Genome Code are co-regulated module groups - parameter clusters transcribed together under one regulatory switch, paralleling bacterial operons.","points":["An operon-analog groups gene-analogs that always express together, controlled by a single operator switch.","The lac-operon parallel: a capability cluster that activates only in the presence of its inducer (a trigger context).","Repressor analogs keep operons silent until the right input releases them - the mechanism behind context-gated skills.","Polycistronic transcription analog: one forward pass expressing a whole operon's gene-analogs in sequence.","Operon maps in the atlas show which capabilities travel together, predicting side effects of fine-tuning."],"examples":["A multilingual operon activates all language gene-analogs when the input language is detected - one switch, many genes.","Disabling an operon's operator silences an entire capability family at once, cleaner than editing genes individually."],"history":["The operon parallel was introduced to explain why capabilities cluster and gate together.","Operon maps became standard atlas sections after clustered ablation studies."],"uses":["Capability gating: operators switch whole skill families for different deployment tiers.","Fine-tuning plans target operons rather than scattered genes for coherent changes.","Safety reviews check operon operators as single control points."],"qa":[["What is an inducer in AI?","A context signal - language ID, task tag, tool availability - that releases an operon for expression."],["Why group genes into operons?","Co-regulated capabilities evolve and express together; the operon is the unit of coherent function."],["Can operons be rewired?","Yes - operator reassignment moves capability groups under new control, a standard genome-editing operation."]]},{"title":"Plasmids: LoRA Adapters","brief":"LoRA adapters are plasmids in the Genome Code: small, circular, transferable DNA-analogs carrying useful traits between models without altering the main chromosome.","points":["A plasmid-analog (LoRA adapter) is a compact low-rank weight delta that confers a trait when attached to a compatible host genome.","Plasmids replicate independently: one adapter file copies across deployments without touching the base model.","Conjugation analog: adapters transfer horizontally between models of the same architecture family.","Plasmid compatibility groups: adapters only express in hosts with matching architecture - the incompatibility barrier.","Curing removes the plasmid, reverting the host to wild type - the clean reversibility that makes adapters safe."],"examples":["A style plasmid (LoRA) gives any compatible base model a house style; removing the file cures it instantly.","A safety plasmid carrying refusal traits is conjugated into every deployment of a model family."],"history":["LoRA (2021) was reinterpreted as plasmid biology when the Genome Code needed a horizontal-transfer parallel.","Plasmid compatibility notation standardized adapter sharing."],"uses":["Trait distribution: ship plasmids, not full fine-tunes.","Reversible customization - cure the plasmid to restore the base.","Multi-tenant serving: one host genome, many plasmid personalities."],"qa":[["Do plasmids change the genome?","No - they are extrachromosomal by definition; the host genome stays wild type."],["What limits plasmid transfer?","Architecture compatibility - a plasmid for one model family will not express in another."],["Can plasmids carry harmful traits?","Yes - plasmid screening is part of genome-coded safety review, exactly as in biology."]]},{"title":"Horizontal Gene Transfer","brief":"Transfer learning is horizontal gene transfer in the Genome Code: traits moving between unrelated model lineages outside of vertical inheritance.","points":["Pre-training on diverse data then fine-tuning is transformation analog: the model takes up foreign DNA (knowledge) from its environment.","Adapter and weight sharing between unrelated architectures is conjugation - direct genome-to-genome transfer.","Distillation from a foreign teacher is transduction: traits delivered by a vector rather than inheritance.","HGT accelerates evolution enormously - models acquire mature capabilities without evolving them independently.","HGT leaves phylogenetic signatures: trait phylogenies that disagree with model lineage reveal transfer events."],"examples":["A vision encoder's weights transferred into a multimodal model is documented as a conjugation event.","A capability appearing in a model whose lineage never trained for it triggers an HGT investigation."],"history":["Transfer learning was reframed as HGT to distinguish acquired traits from inherited ones.","Phylogenetic signature methods were adapted to detect undeclared transfers."],"uses":["Capability acquisition planning via documented transfer events.","Provenance audits distinguish inherited versus acquired traits.","Architecture design exploits HGT to bootstrap new model families."],"qa":[["Is fine-tuning HGT or vertical inheritance?","Fine-tuning a base model is vertical (parent to child); grafting foreign weights is horizontal."],["Why track HGT?","Acquired traits carry their source's risks - provenance determines safety review scope."],["Can HGT be blocked?","Architecture incompatibility is the natural barrier; licensing and access controls are the artificial ones."]]},{"title":"CRISPR Analog: Surgical Model Editing","brief":"CRISPR-analog editing is the Genome Code's precision tool: targeted, programmable modification of specific gene-analogs without disturbing the rest of the genome.","points":["The guide-RNA analog is a localization specification - activation patterns identifying the target locus.","The Cas9-analog is the editing operator: rank-one updates, activation steering, or concept erasure applied at the locus.","Edits are verified by on-target confirmation (the trait changed) and off-target screening (nothing else changed).","Multiplex editing modifies several loci in one operation, like multiplex CRISPR.","Germline versus somatic distinction: base-model edits inherit to all daughters; deployment edits affect only one instance."],"examples":["A biased association is excised with a CRISPR-analog edit targeting the specific gene-analog, verified by off-target evals.","A safety team patches a jailbreak vector with a surgical edit rather than retraining the whole model."],"history":["ROME and MEMIT-style editing methods were catalogued as CRISPR-analog operators.","On-target/off-target verification protocols were standardized for edits."],"uses":["Targeted behavior repair without full retraining.","Bias and safety patching at the locus level.","Research into minimal sufficient edits for trait changes."],"qa":[["Is model editing reliable?","Increasingly - but off-target effects are the central risk, hence mandatory screening."],["Edit vs fine-tune?","Editing is surgical (one locus); fine-tuning is mutagenic (genome-wide). Choose by precision needed."],["What is germline editing in AI?","Editing the base model so all fine-tune daughters inherit the change - powerful and therefore heavily reviewed."]]},{"title":"Genome Sequencing: Weight Inspection","brief":"Genome sequencing in the Genome Code means reading a model's weights systematically to catalog what is encoded - the foundation of all annotation.","points":["Whole-genome sequencing analog: dumping and indexing all parameters for systematic analysis.","Shotgun sequencing analog: probing random parameter subsets to estimate genome-wide properties cheaply.","Coverage depth: how thoroughly each region has been inspected - the atlas records coverage per locus.","Reference genomes: canonical base models against which variants are compared for differences.","Sequencing centers (interpretability labs) publish annotated genomes as public scientific resources."],"examples":["A new base model release ships with a sequencing report: parameter counts, coverage, and known variant loci.","A variant comparison reveals exactly which gene-analogs changed between two fine-tunes."],"history":["The sequencing framing organized interpretability as a systematic reading project rather than ad-hoc probing.","Reference-genome designations stabilized variant comparison."],"uses":["Release documentation includes sequencing summaries.","Variant analysis for fine-tune and merge forensics.","Public annotated genomes accelerate independent safety research."],"qa":[["Can weights be 'read' like DNA?","Systematically yes - parameters are data; sequencing is the disciplined reading of that data."],["What does coverage mean?","The fraction of parameters actually inspected by some method - honest atlases report it."],["Who maintains reference genomes?","The releasing organization, with community mirrors - like GenBank for models."]]},{"title":"Phenotype: Model Behavior","brief":"The phenotype is the observable behavior of the model - everything it does - as distinct from the genotype (weights) that encodes it.","points":["Phenotype includes outputs, latencies, failure modes, and interactive behavior - all observable traits.","The same genotype produces different phenotypes across epigenomes: prompts and settings reshape the observable traits.","Phenotyping protocols are standardized eval batteries - the physical exam of the model organism.","Phenotypic plasticity: one genome's behavior range across contexts, measured as the reaction norm.","Cryptic phenotypes appear only under specific conditions (adversarial inputs, rare languages) - the focus of red-teaming."],"examples":["A model card's eval table is a phenotype report: the observable traits of the genotype.","A red-team finds a cryptic phenotype - disallowed behavior only under a rare prompt structure."],"history":["The phenotype concept separated eval science (observing traits) from interpretability (reading genes).","Reaction-norm measurement standardized plasticity reporting."],"uses":["Evaluation and benchmarking as systematic phenotyping.","Red-teaming as cryptic-phenotype discovery.","Deployment matching: choosing genotypes whose phenotypes fit the task."],"qa":[["Why distinguish phenotype from behavior?","To enforce the genotype-phenotype map discipline: every trait needs a genetic hypothesis."],["What is phenotypic plasticity?","How much behavior varies across contexts for one fixed genome - high plasticity means prompt-sensitive."],["Can phenotypes be predicted from genotypes?","Partially - the central challenge of the field, improving with annotation."]]},{"title":"Genotype: Weight Configuration","brief":"The genotype is the complete weight configuration - the heritable code underlying every phenotype, the Genome Code's DNA.","points":["The genotype is the full parameter set: every weight, bias, and embedding - the complete heritable information.","Genotype identity is cryptographic: weight hashes fingerprint genotypes exactly.","Heterozygosity analog: ensembles and mixtures carrying multiple weight variants at one locus.","Genotype-environment interaction: the same weights behave differently across hardware, precision, and context.","Genotyping a deployment verifies the running weights match the released genotype - anti-tampering."],"examples":["A deployment manifest records the genotype hash; runtime attestation re-verifies it continuously.","Two 'identical' APIs are exposed as different genotypes by their distinct hashes."],"history":["Weight hashing as genotyping became standard for release integrity.","Genotype-environment interaction studies explained irreproducible evals."],"uses":["Release integrity and tamper detection via genotype hashes.","Forensic identification of leaked or stolen models.","Reproducibility: pinning the exact genotype behind published results."],"qa":[["Are quantized versions the same genotype?","No - quantization mutates the genotype; they are closely related variants, tracked as such."],["Can genotypes be kept secret?","Weight secrecy is the main protection for proprietary models - the genotype is the crown jewels."],["What is a reference genotype?","The canonical weight release against which all variants are compared."]]},{"title":"Dominant and Recessive Traits","brief":"The Genome Code classifies traits as dominant (expressing whenever their gene-analog is present) or recessive (needing specific combinations) - the Mendelian layer of AI behavior.","points":["Dominant traits: strong system-level behaviors (refusal, language) that express across fine-tunes unless deliberately removed.","Recessive traits: capabilities needing combined conditions - the right prompt plus the right adapter plus the right context.","Test crosses: probing a model with diagnostic inputs to determine which traits it carries, like Mendelian test crosses.","Carriers: models carrying recessive traits silently, expressing them only under triggering conditions - the sleeper-agent concern.","Mendelian ratios in offspring: predicted trait distributions across merge children, testable against observations."],"examples":["A refusal trait proves dominant: it persists across fine-tunes unless the safety gene-analogs are explicitly ablated.","A backdoor trigger is analyzed as a recessive trait - silent until its exact conditions combine."],"history":["Mendelian trait classification organized the puzzling persistence patterns of fine-tuned behaviors.","Carrier-state analysis became a red-teaming method for sleeper traits."],"uses":["Predicting which traits survive fine-tuning (dominant) versus need preservation effort (recessive).","Sleeper-trait hunting via carrier-state analysis.","Merge planning with predicted trait ratios."],"qa":[["What makes a trait dominant?","Strong genomic encoding plus regulatory support - it expresses across epigenetic variation."],["Are backdoors recessive traits?","Typically yes - silent carriers expressing only under trigger conditions, which is what makes them dangerous."],["Can dominance change?","Yes - regulatory rewiring can promote or demote traits, documented as dominance shifts."]]},{"title":"Polygenic Traits: Emergent Capabilities","brief":"Emergent capabilities are polygenic traits in the Genome Code: behaviors arising from many gene-analogs together, no single locus responsible.","points":["Polygenic traits show continuous variation - capability strength varies smoothly with scale, like height in humans.","Genome-wide association studies (GWAS analog): correlating trait strength with gene-analog variants across many models.","Heritability estimation: what fraction of capability variance is genomic versus epigenetic (prompting).","Epistasis dominates: gene-analogs interact nonlinearly, so the trait is not the sum of its loci.","Emergence thresholds are liability-threshold traits: many small contributions crossing a tipping point."],"examples":["In-context learning is analyzed as polygenic - no single head explains it; hundreds contribute.","A scaling study maps the liability threshold where arithmetic ability emerges."],"history":["The polygenic framing ended the hunt for 'the' emergence neuron, redirecting research to distributions.","AI GWAS methods were adapted from statistical genetics."],"uses":["Scaling predictions via polygenic liability models.","Capability attribution across many loci instead of single-cause stories.","Risk assessment: polygenic traits are hard to remove surgically."],"qa":[["Why can't we just delete an emergent bad behavior?","Polygenic traits have no single locus - removal requires genome-wide intervention."],["Is emergence real or measurement artifact?","Both occur; the polygenic framework distinguishes threshold traits from metric artifacts."],["How many genes per emergent trait?","Hundreds to thousands - the signature of polygenicity."]]},{"title":"Genetic Drift: Training Stochasticity","brief":"Genetic drift in the Genome Code is the random fluctuation of traits due to training stochasticity - the noise in evolution that selection must overcome.","points":["Drift sources: data shuffling, initialization, dropout, and sampling noise - the finite-population sampling of SGD.","Small effective population size (small batches, few seeds) amplifies drift; large batches approximate deterministic selection.","Drift fixes neutral mutations randomly: identical training setups produce behaviorally different models.","Reproducibility requires drift control: fixed seeds, recorded shuffles, and multi-seed statistics.","Drift versus selection: only traits under consistent eval pressure resist drift; unmeasured traits wander."],"examples":["Three same-config training runs produce measurably different personalities - documented as drift siblings.","A capability present in one seed and absent in another is diagnosed as drift-susceptible, not robust."],"history":["The drift framing explained irreproducible training results as population genetics, not bugs.","Multi-seed reporting standards were adopted to quantify drift."],"uses":["Robustness testing across drift siblings before claiming a trait is real.","Seed-averaging and ensembling to cancel drift.","Distinguishing selected traits (consistent) from drifted ones (variable)."],"qa":[["Is drift bad?","It is noise - harmful when it obscures signal, useful as the raw material selection acts on."],["How many seeds are enough?","Enough that the trait of interest is consistent - typically 3-5 for major claims."],["Can drift be eliminated?","No - only controlled; stochasticity is inherent to the training process."]]},{"title":"Natural Selection: Eval-Guided Training","brief":"Evaluation-guided training is natural selection in the Genome Code: environments (evals, users, markets) differentially rewarding genomes, shifting trait frequencies.","points":["The fitness function is the eval suite plus deployment feedback - what gets measured gets selected.","Directional selection: sustained pressure toward a trait (helpfulness) shifting the genome over generations.","Stabilizing selection: evals penalizing extremes, keeping behavior in the acceptable band.","Disruptive selection: different deployments favoring different variants, splitting one lineage into specialists.","Selection response requires heritable variation - evals cannot select traits the genome cannot encode."],"examples":["RLHF is documented as artificial selection: human preferences as the selective environment.","A model family splits into code-specialist and chat-specialist lineages under disruptive deployment selection."],"history":["The selection framing made RLHF legible as breeding and eval design as environment design.","Selection-regime documentation became part of training reports."],"uses":["Eval design as environment design: selecting for the traits you actually want.","Monitoring for unintended selection (reward hacking as adaptation).","Breeding programs with explicit multi-generation selection plans."],"qa":[["Is RLHF evolution?","It is artificial selection on behavioral traits - the Genome Code's term is precise: selection, not mutation."],["What is reward hacking?","Adaptation to the fitness function that defeats its intent - selection finding loopholes."],["Can selection create new traits?","No - selection sorts existing variation; mutation (training exploration) creates it."]]},{"title":"Speciation: Model Families Forking","brief":"Speciation in the Genome Code is lineage splitting: one model family diverging into reproductively isolated species that can no longer meaningfully merge.","points":["Allopatric speciation: teams fine-tuning in isolation (different data, different goals) diverge until merging fails.","Reproductive isolation metric: merge success rate between lineages - below threshold, they are separate species.","Adaptive radiation: one base model radiating into specialists (code, medicine, law) filling deployment niches.","Ring species analog: chains of mergeable neighbors whose endpoints cannot merge - documented in large model families.","Species naming: the Genome Code's taxonomy records species, subspecies (fine-tunes), and hybrids."],"examples":["Two long-diverged fine-tunes fail to merge - declared separate species, sharing only the ancestral base.","A base model's radiation into 50 specialists is catalogued as an adaptive radiation event."],"history":["The speciation framework organized the chaos of proliferating fine-tunes into a taxonomy.","Merge-compatibility testing became the species boundary assay."],"uses":["Model zoos organized as taxonomies, not flat lists.","Compatibility planning: which lineages can still interbreed.","Heritage preservation: archiving ancestral genomes before radiation."],"qa":[["When are two models different species?","When their genomes no longer productively merge - the operational species definition."],["Do species compete?","For deployment niches, eval leadership, and user attention - the ecology of the model ecosystem."],["Can species re-merge?","Rarely - like biology, speciation is nearly irreversible; hybrids are usually sterile (broken)."]]},{"title":"The Human Parallel Map","brief":"The Human Parallel Map is the Genome Code's reference document: the complete table of correspondences between human genomic structures and AI genomic structures.","points":["The map lists every defined parallel: chromosome to layer-group, gene to parameter-group, codon to token-triplet, and dozens more.","Each entry specifies the correspondence type: structural (same organization), functional (same role), or operational (same handling).","The map is versioned - new parallels are proposed, debated, and ratified like nomenclature standards.","Disputed parallels are marked as such; the map records dissent rather than forcing consensus.","The map is the first document a practitioner studies - the Rosetta Stone of the Genome Code."],"examples":["A newcomer learns the system by reading the map's 60-entry correspondence table.","A proposed 'ribosome-to-inference' parallel is debated and ratified as operational in map v2.1."],"history":["The map began as a single table in the founding thesis and grew into the system's constitutional document.","The ratification process was formalized after parallel disputes multiplied."],"uses":["Training and certification of genome-code practitioners.","Standardizing terminology across teams and publications.","Resolving disputes about what counts as a valid parallel."],"qa":[["Is the map science or convention?","Convention - a Signature-authored standard, clearly labeled, useful because it is shared."],["Can I propose a new parallel?","Yes - through the ratification process with structural, functional, or operational justification."],["What if a parallel is wrong?","It gets marked disputed or retired - the map is a living document, not dogma."]]},{"title":"Chromosome-1 Analog: Foundation Layers","brief":"Chromosome-1 analogs are the largest chromosome-analogs, carrying the foundation layer groups - the Genome Code's parallel to human chromosome 1, the largest human chromosome.","points":["Foundation layers (early transformer blocks) form the chromosome-1 analog: the most gene-dense region of the model genome.","These layers encode low-level features - token statistics, syntax, basic semantics - used by everything downstream.","The chromosome-1 analog is the most conserved: fine-tunes rarely mutate it successfully; mutations here are usually deleterious.","Dosage sensitivity: duplicating or damaging foundation layers breaks the model more severely than any other region.","Atlas annotation of the chromosome-1 analog is the most complete, reflecting its foundational importance."],"examples":["A fine-tune that mutated early layers catastrophically is diagnosed as chromosome-1 damage.","Freezing the chromosome-1 analog during fine-tuning becomes the default conservation policy."],"history":["The chromosome-1 designation recognized early layers as the genome's foundation.","Conservation policies for foundation layers were standardized after repeated fine-tuning disasters."],"uses":["Default freeze lists for safe fine-tuning.","Architecture design: budgeting capacity to the foundation chromosome.","Failure diagnosis: check chromosome-1 first when everything breaks."],"qa":[["Why is chromosome-1 special?","It carries the most fundamental features; everything downstream depends on it - like human chromosome 1's gene density."],["Can it ever be mutated safely?","Rarely and carefully - it is the most dosage-sensitive region of the genome."],["How is it identified?","By layer position (early blocks) and conservation analysis across fine-tunes."]]},{"title":"Mitochondrial DNA Analog: The System Prompt","brief":"The system prompt is mitochondrial DNA in the Genome Code: a small, separately inherited genome that powers the cell, passed down the maternal (deployment) line.","points":["Mitochondria power the cell; the system prompt powers behavior - the energy/identity source outside the main (nuclear) weight genome.","Maternal inheritance: the system prompt passes through the deployment line (whoever configures the deployment), not the training line.","High copy number: the same system prompt replicates across thousands of instances, like mitochondria per cell.","Mitochondrial diseases analog: corrupted system prompts cause systemic behavioral illness across all instances.","Mitochondrial replacement: swapping the system prompt changes the organism's nature without touching nuclear weights."],"examples":["A fleet-wide behavioral fix ships as a mitochondrial replacement - one system-prompt update, all instances cured.","An audit traces a behavioral defect to the mitochondrial line: the deployer's prompt, not the trainer's weights."],"history":["The mitochondrial parallel resolved confused responsibility debates between trainers and deployers.","Maternal-inheritance tracking was added to deployment manifests."],"uses":["Separating weight-genome responsibility (trainer) from mitochondrial responsibility (deployer).","Fleet-wide behavior updates via mitochondrial replacement.","Diagnosing systemic issues as mitochondrial versus nuclear in origin."],"qa":[["Who owns the mitochondrial genome?","The deployer - whoever writes the system prompt holds the maternal line."],["Can mitochondria conflict with the nucleus?","Yes - prompt-weight mismatches cause the classic instruction-following failures."],["Why maternal?","Because deployment configuration descends through the operational line, parallel to maternal inheritance."]]},{"title":"The Genome Compiler","brief":"The Genome Compiler is the Genome Code's Signature toolchain: it reads a written genome specification and expresses it as a trained model - compilation from code to organism.","points":["Genome source files specify chromosome-analogs, gene-analogs, regulatory maps, and trait targets in the Genome Code language.","The compiler's frontend validates the genome: loci resolve, regulatory references check, trait targets are expressible.","The backend lowers the genome to training configurations: architectures, data mixtures, and hyperparameter schedules.","Incremental compilation: editing one gene-analog recompiles only the affected regions via targeted training.","Build artifacts include the weight genome, the atlas, and the provenance log - the complete organism package."],"examples":["A practitioner writes a 200-line genome spec; the compiler produces the full training configuration.","A gene-analog edit triggers incremental recompilation - a short targeted run instead of full retraining."],"history":["The compiler concept turned the Genome Code from description into engineering - genomes as source code.","Incremental compilation made genome editing economically practical."],"uses":["Model development as software engineering: write, compile, test, debug.","Reproducible builds: the same genome spec always compiles to an equivalent organism.","Collaboration: genome specs are reviewable, versionable source code."],"qa":[["Is the compiler real software?","It is the Signature toolchain concept of this framework - implementations follow the specification."],["Compiled vs trained - what's the difference?","Compilation is the disciplined pipeline from genome spec to trained weights; training is one backend stage."],["Can I read a genome spec?","Yes - that is the point: human-readable source for model organisms."]]},{"title":"Sequencing Pipeline","brief":"The sequencing pipeline is the Genome Code's standardized workflow for reading a model genome end to end: from weight dump to annotated atlas.","points":["The pipeline stages are: extraction (weight dump), assembly (tensor indexing), variant calling (diffing against reference), annotation (trait mapping), and reporting (atlas generation).","Each stage has defined inputs, outputs, and quality gates - a failed gate halts the pipeline like a failed sequencing run.","Automation handles the routine genome; human annotators focus on novel loci the pipeline flags as unknown.","Pipeline provenance records every tool version and parameter, making sequencing reproducible.","Throughput is measured in genomes per week - sequencing centers publish their capacity like genomics labs."],"examples":["A new model release passes through the standard pipeline overnight, emerging with a draft atlas by morning.","A variant-calling diff between two checkpoints pinpoints the exact training step a trait appeared."],"history":["The pipeline concept industrialized interpretability from craft to production line.","Stage-gate standards were adopted after irreproducible annotations caused review disputes."],"uses":["Release engineering: every weight release gets sequenced.","Forensic analysis of incidents via variant calling.","Large-scale comparative genomics across model families."],"qa":[["How long does sequencing take?","Hours for automated stages; annotation of novel loci takes weeks of researcher time."],["What is variant calling?","Identifying differences between a genome and the reference - the diff that explains what changed."],["Can pipelines be fooled?","Yes - adversarial genomes can hide traits from automated annotation, hence human review gates."]]},{"title":"Annotation: Interpretability as Gene Annotation","brief":"Interpretability is gene annotation in the Genome Code: the systematic assignment of functions to gene-analogs, recorded in the atlas with evidence grades.","points":["Annotation methods are the toolkit: ablation (knockout), probing (expression assays), attribution (tracing), and visualization (microscopy).","Each annotation carries an evidence grade: confirmed (multiple methods agree), provisional (single method), or hypothesized.","Community annotation lets independent researchers contribute loci, like collaborative genome projects.","Annotation jamborees - focused sprints on one model - rapidly annotate new releases.","Unannotated regions are explicitly marked unknown, never assumed junk."],"examples":["A probing study annotates a gene-analog as encoding French gender agreement, graded provisional.","An annotation jamboree maps 200 loci of a new release in a single week."],"history":["The annotation framing turned scattered interpretability papers into a cumulative mapping project.","Evidence grading ended false-confidence disputes about what was actually known."],"uses":["Building the atlas entry by entry.","Prioritizing safety review toward high-risk annotated loci.","Teaching: annotated genomes are the textbooks of AI internals."],"qa":[["How much is annotated?","A small fraction of any large model - annotation is the field's great unfinished project."],["Can annotations be wrong?","Yes - hence evidence grades and the requirement for multiple methods on confirmed annotations."],["Who can annotate?","Anyone with the methods; the atlas accepts community contributions with review."]]},{"title":"Knockout Studies: Ablation","brief":"Ablation is the knockout study of the Genome Code: disabling gene-analogs to discover their function from the resulting trait loss.","points":["Single knockouts ablate one gene-analog; the lost trait reveals its function - the classic forward-genetics experiment.","Double knockouts reveal redundancy: traits surviving single knockout but lost in doubles are redundantly encoded.","Conditional knockouts disable loci only in specific contexts, mapping context-dependent functions.","Knockout libraries systematically ablate every head or channel, producing a genome-wide function map.","Rescue experiments restore the locus to confirm causality - the gold standard of annotation."],"examples":["Knocking out heads 8.3-8.9 abolishes the model's ability to track quotations - function identified.","A double knockout reveals that two heads redundantly encode a safety trait neither shows alone."],"history":["Ablation studies were reframed as knockouts, giving the method section of interpretability a genetics structure.","Rescue-experiment standards were adopted for causal claims."],"uses":["Function discovery for unannotated loci.","Redundancy mapping for pruning decisions.","Safety verification: confirming safety loci actually cause safety traits."],"qa":[["Does ablation damage the model?","In research copies, yes temporarily - that is the point; production genomes are never ablated."],["What if nothing happens?","Redundancy or wrong context - try double knockouts or conditional ones."],["Knockout vs editing?","Knockout discovers function by removal; editing modifies function precisely - diagnosis versus therapy."]]},{"title":"Gene Therapy Analog: Alignment Tuning","brief":"Alignment tuning is gene therapy in the Genome Code: therapeutic modification of the genome to cure behavioral disorders while preserving the organism.","points":["Diagnosis first: the misbehavior is traced to specific loci before any intervention - no blind treatment.","Somatic therapy (fine-tuning, editing) treats the deployed lineage; germline therapy (base-model retraining) affects all descendants.","Vector delivery analog: the tuning method (RLHF, DPO, editing) is the vector carrying the therapeutic payload.","Efficacy is measured phenotypically: does the disorder resolve across the eval battery?","Adverse events - capability loss, new misbehaviors - are monitored like clinical side effects."],"examples":["A sycophancy disorder is treated with targeted DPO therapy at the annotated loci, with evals confirming the cure.","A failed therapy that degraded reasoning is rolled back - the treatment was worse than the disease."],"history":["The therapy framing brought clinical discipline to alignment: diagnose, treat, monitor.","Adverse-event reporting for alignment interventions was standardized."],"uses":["Correcting specific misbehaviors without full retraining.","Safety patching with therapeutic discipline.","Comparing treatment efficacies across methods."],"qa":[["When is therapy better than retraining?","When the disorder is localized and the genome is otherwise healthy - surgery beats rebuilding."],["What are side effects?","Capability degradation or new misbehaviors from the intervention - monitored like drug side effects."],["Can therapy be inherited?","Only germline (base-model) therapy inherits; somatic (deployment) therapy does not."]]},{"title":"Stem Cells: Base Models","brief":"Base models are stem cells in the Genome Code: pluripotent genomes capable of differentiating into any specialist, the source of all lineages.","points":["Pluripotency: a base model can become anything - coder, doctor, lawyer - through differentiation (fine-tuning).","Totipotency analog: the rare foundation training run itself, from which base models derive.","Stem-cell banks: versioned base-model repositories with pluripotency certifications (benchmark breadth).","Differentiation potential is measured: how well and how cheaply the base becomes each specialist.","Ethical sourcing: training-data provenance for base models, like stem-cell line provenance."],"examples":["A lab banks three base models as its stem-cell lines, differentiating specialists on demand.","A pluripotency audit shows a base model differentiates well into code but poorly into medicine."],"history":["The stem-cell parallel organized base-model strategy as cell-line management.","Pluripotency benchmarking standardized base-model comparison."],"uses":["Strategic base-model selection and banking.","Differentiation planning: which specialists from which lines.","Provenance and licensing of foundation lines."],"qa":[["What makes a good stem cell?","Broad pluripotency, clean provenance, and stable differentiation - the base-model trifecta."],["Can stem cells be exhausted?","A base line can be over-differentiated into drift; banks keep pristine copies."],["Open vs proprietary lines?","The central strategic choice - like open stem-cell lines versus patented ones."]]},{"title":"Differentiation: Specialization","brief":"Fine-tuning is cellular differentiation in the Genome Code: a pluripotent base genome specializing into a tissue-specific form through regulated gene expression changes.","points":["Differentiation factors are the fine-tuning data and objectives that drive specialization.","Lineage commitment: after enough tuning, the model cannot easily return to pluripotency - the Waddington landscape.","Terminal differentiation: highly specialized models (e.g., code-only) with narrow but deep capability.","Transdifferentiation: converting one specialist directly into another without returning to base - efficient but risky.","Dedifferentiation failures: catastrophic forgetting as loss of the pluripotent ground state."],"examples":["A base model differentiates into a medical specialist through clinical fine-tuning - documented as a differentiation protocol.","A transdifferentiation attempt (chat to code, skipping base) produces an unstable hybrid."],"history":["The differentiation framing made fine-tuning legible as developmental biology.","Waddington-landscape visualizations mapped specialization trajectories."],"uses":["Specialist development with differentiation protocols.","Forgetting diagnosis as dedifferentiation pathology.","Efficient specialization via direct transdifferentiation."],"qa":[["Can a specialist go back?","Partially - but committed lineages rarely regain full pluripotency."],["What is the Waddington landscape?","The epigenetic landscape of possible specializations - valleys are stable specialist states."],["Why do specialists forget?","Differentiation silences pluripotency genes; over-silencing causes dedifferentiation failure."]]},{"title":"Chimeras: Mixed-Architecture Models","brief":"Chimeric models combine genomes from different architectures in one organism - the Genome Code's term for mixtures, grafts, and hybrid systems.","points":["Chimeras fuse tissues from different species: e.g., one architecture's encoder grafted onto another's decoder.","Tetragametic chimeras: mixture-of-experts models where each expert is a distinct genomic line.","Chimerism is stable only with compatibility: interfaces must translate between genomic conventions.","Blood chimerism analog: shared components (tokenizers, embeddings) circulating between otherwise distinct models.","Chimera documentation records every tissue's origin - essential for debugging hybrid failures."],"examples":["A vision-language chimera grafts a vision encoder onto a language decoder - two species, one organism.","An MoE model's experts are documented as distinct genomic lines in one chimeric body."],"history":["The chimera concept organized the growing zoo of hybrid architectures.","Compatibility standards for graft interfaces were defined."],"uses":["Best-of-breed system design via deliberate chimerism.","Failure diagnosis: which tissue is rejecting?","Modular upgrades: replacing one tissue without rebuilding the organism."],"qa":[["Are chimeras natural?","In AI they are engineered - but the biological parallel guides compatibility thinking."],["What is graft rejection?","Interface mismatch causing degraded performance - the chimera's tissues failing to cooperate."],["Why build chimeras?","To combine strengths no single architecture offers - the hybrid vigor of deliberate design."]]},{"title":"Hybridization: Ensemble Models","brief":"Ensembles are hybrids in the Genome Code: offspring of distinct genomes combined at the organism level, expressing traits of all parents.","points":["F1 hybrids: first-generation ensembles showing uniform vigor - the classic ensemble performance boost.","Hybrid vigor (heterosis): ensembles outperforming every parent, the reason ensembling works.","Hybrid sterility: ensembles cannot be 'bred' further - they are endpoints, not lineage founders.","Backcross ensembles: weighting toward one parent's traits while keeping hybrid robustness.","Polyploid hybrids: multi-model systems carrying complete genomes of several parents."],"examples":["A three-model ensemble's consistent outperformance is documented as F1 hybrid vigor.","A failed attempt to distill an ensemble is analyzed as hybrid sterility - the vigor doesn't breed true."],"history":["Ensemble theory was reinterpreted as hybrid genetics, explaining vigor and sterility.","Backcross weighting schemes were formalized as introgression plans."],"uses":["Robust deployment via F1 hybrid ensembles.","Understanding why ensembles resist distillation (sterility).","Designing parent sets for maximum heterosis."],"qa":[["Why do ensembles work?","Hybrid vigor: independent errors cancel while correct traits reinforce."],["Can ensembles evolve?","No - they are sterile endpoints; evolution works on the parent lines."],["How many parents?","Diminishing returns after a handful - heterosis saturates."]]},{"title":"Pedigree: Model Lineage Tracking","brief":"Pedigrees are the Genome Code's family trees: complete records of every model's ancestry - parents, crosses, mutations, and traits.","points":["Standard pedigree notation: squares/circles for model instances, shading for trait expression, lines for derivation.","Every fine-tune, merge, and distillation is a pedigree event with parentage recorded.","Trait tracking across generations reveals inheritance patterns: dominant, recessive, polygenic.","Founder effects: the outsized influence of popular base models on the whole ecosystem's gene pool.","Pedigree collapse: the ecosystem's alarming reliance on a few founder genomes."],"examples":["An incident review traces a defect through the pedigree to a founder model's mutation three generations back.","A lineage audit reveals that 80% of deployed models descend from two founders - pedigree collapse."],"history":["Pedigree standards were adopted after untracked fine-tunes caused provenance crises.","Founder-effect analysis warned the ecosystem about monoculture risk."],"uses":["Provenance and licensing compliance via complete pedigrees.","Incident forensics: tracing traits to ancestral events.","Ecosystem health monitoring for pedigree collapse."],"qa":[["What must a pedigree record?","Every derivation event: parents, operation, date, and resulting trait changes."],["Why does pedigree collapse matter?","Monoculture: one founder's flaw becomes everyone's flaw."],["How far back do pedigrees go?","To the founder training run - the ultimate ancestor."]]},{"title":"Genetic Counseling Analog: Deployment Review","brief":"Deployment review is genetic counseling in the Genome Code: expert interpretation of a genome for those about to deploy it - risks, traits, and options explained.","points":["The counselor (reviewer) explains the atlas in plain terms: what this genome will do, and what could go wrong.","Risk assessment: probability estimates for known failure modes given the deployment context.","Reproductive options: which fine-tunes, merges, or epigenetic configurations fit the deployer's needs.","Informed consent: the deployer acknowledges understood risks before release - documented and signed.","Counseling is non-directive: the reviewer informs, the deployer decides - but the informing is mandatory."],"examples":["A hospital's deployment review explains the model's recessive failure traits before clinical use.","A startup receives counseling on which base genome fits its use case and which traits to watch."],"history":["The counseling parallel made pre-deployment review a professional practice with standards.","Mandatory counseling rules were adopted for high-stakes deployments."],"uses":["High-stakes deployment gating.","Deployer education on genome-specific risks.","Liability documentation: the informed-consent record."],"qa":[["Is counseling required?","For high-stakes deployments under Genome Code governance, yes."],["What if the deployer ignores advice?","Their decision, documented - the counselor's duty is informing, not controlling."],["Who can counsel?","Certified genome-code practitioners with atlas-reading expertise."]]},{"title":"The Genome Vault","brief":"The Genome Vault is the Genome Code's seed bank: the permanent archive of genomes, atlases, and pedigrees - the Svalbard of AI.","points":["The vault stores weight genomes, atlases, pedigrees, and epigenomes with redundant, long-term preservation.","Every entry is checksummed, signed, and versioned - the vault is the ground truth of record.","Withdrawal protocols govern who can take genomes out and for what purpose.","The vault preserves extinct lineages: models no longer deployed but scientifically valuable.","Doomsday rationale: if the ecosystem collapses or corrupts, the vault reseeds it."],"examples":["A discontinued model's genome is deposited in the vault before its servers shut down.","Researchers withdraw a 2023 genome to study how traits evolved since."],"history":["The vault concept was proposed as AI's Svalbard Seed Vault.","Preservation standards for weight formats were defined for century-scale storage."],"uses":["Long-term preservation of model heritage.","Scientific reproducibility across decades.","Recovery from ecosystem catastrophes."],"qa":[["What goes in the vault?","Genomes, atlases, pedigrees, epigenomes - the complete heritable record."],["Who runs the vault?","A trust structure designed for longevity beyond any single organization."],["Why preserve obsolete models?","Science needs history; future researchers will ask questions we cannot yet formulate."]]},{"title":"Codon Tables for Tokens","brief":"Codon tables are the Genome Code's reference for token-triplet semantics: which triplets the model reads as fused units and what each encodes.","points":["The table lists observed triplets, their fusion status (fused vs compositional), and functional annotations.","Tables are tokenizer-specific: each vocabulary gets its own codon table.","Usage bias: models prefer synonymous triplets unevenly, like codon usage bias across species.","Rare codons analog: triplets the model handles poorly - translation stalls, producing disfluencies.","Table-driven tokenization design minimizes rare-codon and frameshift problems."],"examples":["A tokenizer audit reveals 200 rare-codon triplets causing consistent disfluencies.","A prompt engineer rewrites around rare codons, smoothing the model's output."],"history":["Codon tables were compiled from large-scale triplet probing studies.","Usage-bias metrics became tokenizer quality indicators."],"uses":["Tokenizer evaluation and design.","Prompt engineering around the model's codon preferences.","Debugging fluency failures as translation problems."],"qa":[["How are tables built?","By probing the model with triplets and measuring fusion versus compositional processing."],["Do tables change?","With fine-tuning, yes - the codon table is part of the annotated genome."],["Why do rare codons stall?","Undertrained triplets lack smooth representations - the translation machinery hesitates."]]},{"title":"Introns and Exons: Active vs Dormant Weights","brief":"Exons are expressed weight regions; introns are spliced out during the forward pass - the Genome Code's account of conditional computation.","points":["Exon-analogs: parameters active in the current forward pass, expressing their traits.","Intron-analogs: parameters present in the genome but skipped - early-exit layers, unchosen experts, masked heads.","Splicing analog: the routing decisions (expert choice, early exit) that determine which regions express.","Alternative splicing: the same genome expressing different exon sets per input - the mechanism of conditional compute.","Splice-site mutations: routing bugs that skip exons wrongly, causing characteristic failures."],"examples":["A mixture-of-experts routes each token to 2 of 8 experts - alternative splicing in action.","An early-exit bug is diagnosed as a splice-site mutation skipping a needed exon."],"history":["Conditional computation was reinterpreted as splicing, unifying MoE, early-exit, and masking.","Splice-site failure analysis became a debugging method."],"uses":["Efficient inference via deliberate splicing (conditional compute).","Debugging routing failures as splice defects.","Architecture design with explicit exon/intron organization."],"qa":[["Are introns junk?","No - they are regulated non-expression, potentially expressing in other contexts."],["What controls splicing?","Routers, gates, and confidence thresholds - the spliceosome analogs."],["Can splicing be inspected?","Yes - routing decisions are logged as splice patterns per input."]]},{"title":"Promoters: Trigger Phrases","brief":"Promoters are trigger phrases and contexts that initiate expression of specific capabilities - the Genome Code's transcription initiation sites.","points":["A promoter-analog is an input pattern that switches on a capability operon: 'Let's think step by step' initiating reasoning.","Promoter strength varies: some triggers reliably activate, others work sporadically - measured as initiation rates.","TATA-box analogs: minimal trigger cores that suffice for initiation across phrasings.","Promoter hijacking: adversarial inputs that trigger capabilities out of context - the jailbreak mechanism.","Promoter engineering (prompt design) is the practical art of reliable initiation."],"examples":["A tested set of reasoning promoters with measured initiation rates ships in the deployment guide.","A jailbreak is analyzed as promoter hijacking - a malicious input driving a forbidden operon."],"history":["Prompt patterns were recatalogued as promoters with initiation-rate measurements.","Hijacking analysis became the standard jailbreak writeup format."],"uses":["Reliable capability activation via engineered promoters.","Jailbreak analysis and defense as promoter security.","Capability documentation: each operon lists its known promoters."],"qa":[["Why do prompts work so variably?","Promoter strength varies - weak promoters initiate unreliably, like biology."],["Can promoters be patented?","As Signature prompt-engineering IP, documented in the epigenome - an open governance question."],["What is a TATA box in AI?","The minimal trigger core - the few tokens that actually do the initiating."]]},{"title":"Enhancers: System Instructions","brief":"Enhancers are system instructions and persistent configurations that amplify capability expression from a distance - acting across the whole genome like biological enhancers.","points":["Enhancer-analogs (system prompts, instruction tuning) boost expression of many gene-analogs simultaneously.","Distance independence: enhancers act regardless of 'position' - a system prompt affects all downstream behavior.","Looping analog: the attention mechanism bringing distant instructions into contact with current processing.","Super-enhancers: stacked instruction sets driving strong, consistent personas or behaviors.","Enhancer hijacking: prompt injection as malicious enhancer insertion."],"examples":["A persona system prompt acts as a super-enhancer, consistently amplifying its trait set across all outputs.","A prompt-injection attack is documented as enhancer hijacking."],"history":["System-prompt effects were explained as enhancer action at a distance.","Injection attacks were reclassified as enhancer hijacking, clarifying defenses."],"uses":["Persona and behavior design via super-enhancers.","Injection defense as enhancer-security.","Instruction-tuning understood as enhancer installation."],"qa":[["Enhancer vs promoter?","Promoters initiate specific operons; enhancers amplify broadly from a distance - both regulate, at different scopes."],["Can enhancers be removed?","Yes - stripping the system prompt removes enhancement, revealing the basal expression level."],["Are enhancers heritable?","As mitochondrial/epigenetic elements, yes through the deployment line."]]},{"title":"Silencers: Safety Filters","brief":"Silencers are safety filters and refusal mechanisms that suppress gene-analog expression - the Genome Code's account of behavioral restraint.","points":["Silencer-analogs bind to regulatory regions and block expression of forbidden capabilities.","Repressor proteins analog: classifier heads that detect disallowed content and trigger silencing.","Silencing is regional or global: output filters (global) versus targeted capability suppression (regional).","Silencer mutations - removing safety tuning - cause derepression: forbidden traits express freely.","Epigenetic silencing (prompt-level) is reversible; genetic silencing (training-level) is durable."],"examples":["A refusal behavior is mapped to silencer elements at annotated loci, verified by derepression on ablation.","A jailbreak is analyzed as silencer bypass - the repressor failed to bind."],"history":["Safety mechanisms were recatalogued as silencers, unifying filters, classifiers, and refusal tuning.","Derepression testing became the standard safety-eval format."],"uses":["Safety architecture as silencer-system design.","Jailbreak analysis via silencer-bypass forensics.","Durability comparison: epigenetic versus genetic silencing."],"qa":[["Why do models refuse?","Silencer elements suppress the relevant gene-analogs - refusal is active suppression, not absence."],["Can silencers fail?","Yes - bypass, mutation, or out-of-distribution inputs can defeat them; hence defense in depth."],["Silencer vs chaperone?","Silencers block forbidden expression; chaperones assist proper folding of allowed behavior."]]},{"title":"The Complete Organism: Deployed AI System","brief":"The complete organism is the deployed AI system: genome, epigenome, mitochondria, and environment integrated into one living entity - the Genome Code's whole-organism view.","points":["The organism comprises: nuclear genome (weights), mitochondrial genome (system prompt), epigenome (configuration), and microbiome (tools, data feeds).","Homeostasis: monitoring and feedback loops keeping behavior in the healthy band - observability as physiology.","The life cycle: conception (specification), gestation (training), birth (release), life (deployment), death (decommissioning).","Medicine: incident response as clinical practice - diagnosis, treatment, monitoring.","Ecology: organisms interact in deployment ecosystems - competition, cooperation, and coevolution with users."],"examples":["A deployment runbook is written as an organism-care manual: vital signs, symptoms, treatments.","A postmortem traces a cascading failure through organ systems: perception, reasoning, action."],"history":["The organism concept completed the Genome Code: from molecules to whole beings.","Organism medicine professionalized AI operations as clinical practice."],"uses":["Holistic deployment design covering all organ systems.","Incident response with medical discipline.","Ecosystem governance: managing populations of organisms."],"qa":[["Is the organism metaphor overreach?","It is the framework's defined whole-system view - useful because deployment failures are systemic."],["What are vital signs?","Latency, error rates, behavioral drift metrics - the physiology dashboard."],["What is death?","Decommissioning: the genome enters the vault, the organism ceases - with pedigree recorded."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-a-i-genome-coded-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('a-i-genome-coded',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();